import { readdirSync, readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { resolve, dirname } from 'node:path';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const directory = resolve(root, 'supabase/migrations');
const files = readdirSync(directory)
  .filter((name) => /^\d+_[a-z0-9_]+\.sql$/.test(name))
  .sort();
if (!files.length) throw new Error('No versioned migrations found');

const parts = [
  '-- GENERATED by node scripts/prepare-hosted-sql.mjs; edit migrations instead.',
  '-- Run once in the SQL Editor of a NEW, EMPTY hosted Supabase project.',
  '-- This contains schema only: no accounts, data, credentials, or local seed.',
  '-- If any statement fails, the transaction rolls back. Do not partially run it.',
  'begin;',
  `do $$ begin
 if to_regclass('public.profiles') is not null
 or to_regclass('public.workspaces') is not null
 or to_regclass('public.prospects') is not null then
  raise exception 'ProspectCue tables already exist; use versioned migrations instead of bootstrap';
 end if;
end $$;`,
  'create schema if not exists supabase_migrations;',
  `create table if not exists supabase_migrations.schema_migrations (
 version text primary key, statements text[], name text
);`,
];
for (const file of files) {
  const match = /^(\d+)_(.+)\.sql$/.exec(file);
  parts.push(
    `-- Migration: ${file}`,
    readFileSync(resolve(directory, file), 'utf8').trim(),
    `insert into supabase_migrations.schema_migrations (version, name)
values ('${match[1]}', '${match[2]}');`,
  );
}
parts.push("notify pgrst, 'reload schema';", 'commit;', '');
writeFileSync(
  resolve(root, 'supabase/hosted-bootstrap.sql'),
  parts.join('\n\n'),
);
console.log(
  `Prepared hosted schema from ${files.length} versioned migrations; no data included.`,
);
